import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../providers/wallet/public_private_balance_state_provider.dart';
import '../../../providers/wallet/wallet_balance_toggle_state_provider.dart';
import '../../../themes/stack_colors.dart';
import '../../../utilities/amount/amount.dart';
import '../../../utilities/amount/amount_formatter.dart';
import '../../../utilities/constants.dart';
import '../../../utilities/enums/wallet_balance_toggle_state.dart';
import '../../../utilities/text_styles.dart';
import '../../../wallets/crypto_currency/crypto_currency.dart';
import '../../../wallets/isar/providers/wallet_info_provider.dart';

enum _BalanceType { total, available, full, privateAvailable, privateFull }

class WalletBalanceToggleSheet extends ConsumerWidget {
  const WalletBalanceToggleSheet({super.key, required this.walletId});

  final String walletId;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final maxHeight = MediaQuery.of(context).size.height * 0.90;

    final coin = ref.watch(pWalletCoin(walletId));
    // The PIVX shield balance is the secondary balance.
    final balancePrivate = ref.watch(pWalletBalanceSecondary(walletId));

    final balance = ref.watch(pWalletBalance(walletId));

    _BalanceType _bal =
        ref.watch(walletBalanceToggleStateProvider) ==
            WalletBalanceToggleState.available
        ? _BalanceType.available
        : _BalanceType.full;

    if (ref.watch(publicPrivateBalanceStateProvider) == BalanceType.private) {
      _bal = _bal == _BalanceType.available
          ? _BalanceType.privateAvailable
          : _BalanceType.privateFull;
    }

    if (ref.watch(showTotalBalanceProvider)) {
      _bal = _BalanceType.total;
    }

    return Container(
      decoration: BoxDecoration(
        color: Theme.of(context).extension<StackColors>()!.popupBG,
        borderRadius: const BorderRadius.vertical(top: Radius.circular(20)),
      ),
      child: LimitedBox(
        maxHeight: maxHeight,
        child: Padding(
          padding: const EdgeInsets.only(
            left: 16,
            right: 16,
            top: 10,
            bottom: 0,
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  decoration: BoxDecoration(
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .textFieldDefaultBG,
                    borderRadius: BorderRadius.circular(
                      Constants.size.circularBorderRadius,
                    ),
                  ),
                  width: 60,
                  height: 4,
                ),
              ),
              const SizedBox(height: 36),
              Padding(
                padding: const EdgeInsets.only(left: 8.0),
                child: Text(
                  "Wallet balance",
                  style: STextStyles.pageTitleH2(context),
                  textAlign: TextAlign.left,
                ),
              ),
              const SizedBox(height: 24),
              BalanceSelector(
                title: "Total balance",
                coin: coin,
                balance: balance.total + balancePrivate.total,
                onPressed: () {
                  ref.read(showTotalBalanceProvider.notifier).state = true;
                  Navigator.of(context).pop();
                },
                onChanged: (_) {
                  ref.read(showTotalBalanceProvider.notifier).state = true;
                  Navigator.of(context).pop();
                },
                value: _BalanceType.total,
                groupValue: _bal,
              ),
              const SizedBox(height: 12),
              BalanceSelector(
                title: "Available public balance",
                coin: coin,
                balance: balance.spendable,
                onPressed: () {
                  ref.read(walletBalanceToggleStateProvider.notifier).state =
                      WalletBalanceToggleState.available;
                  ref.read(publicPrivateBalanceStateProvider.notifier).state =
                      BalanceType.public;
                  ref.read(showTotalBalanceProvider.notifier).state = false;
                  Navigator.of(context).pop();
                },
                onChanged: (_) {
                  ref.read(walletBalanceToggleStateProvider.notifier).state =
                      WalletBalanceToggleState.available;
                  ref.read(publicPrivateBalanceStateProvider.notifier).state =
                      BalanceType.public;
                  ref.read(showTotalBalanceProvider.notifier).state = false;
                  Navigator.of(context).pop();
                },
                value: _BalanceType.available,
                groupValue: _bal,
              ),
              const SizedBox(height: 12),
              BalanceSelector(
                title: "Full public balance",
                coin: coin,
                balance: balance.total,
                onPressed: () {
                  ref.read(walletBalanceToggleStateProvider.notifier).state =
                      WalletBalanceToggleState.full;
                  ref.read(publicPrivateBalanceStateProvider.notifier).state =
                      BalanceType.public;
                  ref.read(showTotalBalanceProvider.notifier).state = false;
                  Navigator.of(context).pop();
                },
                onChanged: (_) {
                  ref.read(walletBalanceToggleStateProvider.notifier).state =
                      WalletBalanceToggleState.full;
                  ref.read(publicPrivateBalanceStateProvider.notifier).state =
                      BalanceType.public;
                  ref.read(showTotalBalanceProvider.notifier).state = false;
                  Navigator.of(context).pop();
                },
                value: _BalanceType.full,
                groupValue: _bal,
              ),
              const SizedBox(height: 12),
              BalanceSelector(
                title: "Available Private balance",
                coin: coin,
                balance: balancePrivate.spendable,
                onPressed: () {
                  ref.read(walletBalanceToggleStateProvider.notifier).state =
                      WalletBalanceToggleState.available;
                  ref.read(publicPrivateBalanceStateProvider.notifier).state =
                      BalanceType.private;
                  ref.read(showTotalBalanceProvider.notifier).state = false;
                  Navigator.of(context).pop();
                },
                onChanged: (_) {
                  ref.read(walletBalanceToggleStateProvider.notifier).state =
                      WalletBalanceToggleState.available;
                  ref.read(publicPrivateBalanceStateProvider.notifier).state =
                      BalanceType.private;
                  ref.read(showTotalBalanceProvider.notifier).state = false;
                  Navigator.of(context).pop();
                },
                value: _BalanceType.privateAvailable,
                groupValue: _bal,
              ),
              const SizedBox(height: 12),
              BalanceSelector(
                title: "Full Private balance",
                coin: coin,
                balance: balancePrivate.total,
                onPressed: () {
                  ref.read(walletBalanceToggleStateProvider.notifier).state =
                      WalletBalanceToggleState.full;
                  ref.read(publicPrivateBalanceStateProvider.notifier).state =
                      BalanceType.private;
                  ref.read(showTotalBalanceProvider.notifier).state = false;
                  Navigator.of(context).pop();
                },
                onChanged: (_) {
                  ref.read(walletBalanceToggleStateProvider.notifier).state =
                      WalletBalanceToggleState.full;
                  ref.read(publicPrivateBalanceStateProvider.notifier).state =
                      BalanceType.private;
                  ref.read(showTotalBalanceProvider.notifier).state = false;
                  Navigator.of(context).pop();
                },
                value: _BalanceType.privateFull,
                groupValue: _bal,
              ),
              const SizedBox(height: 40),
            ],
          ),
        ),
      ),
    );
  }
}

class BalanceSelector<T> extends ConsumerWidget {
  const BalanceSelector({
    super.key,
    required this.title,
    required this.coin,
    required this.balance,
    required this.onPressed,
    required this.onChanged,
    required this.value,
    required this.groupValue,
  });

  final String title;
  final CryptoCurrency coin;
  final Amount balance;
  final VoidCallback onPressed;
  final void Function(T?) onChanged;
  final T value;
  final T? groupValue;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return RawMaterialButton(
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(
          Constants.size.circularBorderRadius,
        ),
      ),
      onPressed: onPressed,
      child: Container(
        color: Colors.transparent,
        padding: const EdgeInsets.all(8),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            SizedBox(
              width: 20,
              height: 20,
              child: Radio(
                activeColor: Theme.of(context)
                    .extension<StackColors>()!
                    .radioButtonIconEnabled,
                value: value,
                groupValue: groupValue,
                onChanged: onChanged,
              ),
            ),
            const SizedBox(width: 12),
            Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(title, style: STextStyles.titleBold12(context)),
                const SizedBox(height: 2),
                Text(
                  ref.watch(pAmountFormatter(coin)).format(balance),
                  style: STextStyles.itemSubtitle12(context).copyWith(
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .textSubtitle1,
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}
